WITH kept AS (SELECT s.* FROM stores s WHERE NOT EXISTS (SELECT 1 FROM store_sales x WHERE x.store_id = s.id AND x.store_id IN (3, 4))), latest_match AS (SELECT s.*, latest.store_sale_sale_date, latest.revenue FROM kept s JOIN LATERAL (SELECT c.sale_date AS store_sale_sale_date, c.revenue FROM store_sales c WHERE c.store_id = s.id ORDER BY c.revenue DESC, c.id DESC LIMIT 1) latest ON TRUE), matched_keys AS (SELECT id, city FROM latest_match EXCEPT DISTINCT SELECT id, city FROM stores WHERE city = 'Tokyo'), reconciled AS (SELECT s.* FROM latest_match s JOIN matched_keys k ON s.id = k.id AND s.city = k.city), base AS (SELECT *, SUBSTRING(region, 1, 2) region_prefix, COALESCE(region, 'UNKNOWN') region_filled FROM reconciled WHERE region IS NOT NULL) SELECT CASE WHEN revenue >= 4100 THEN 'PREMIUM' ELSE 'STANDARD' END AS revenue_tier, SUM(CASE WHEN city = 'Berlin' THEN sqft ELSE 0 END) AS berlin_sqft, APPROX_PERCENTILE(revenue, ARRAY(0.25, 0.5, 0.75)) AS revenue_quartiles, COUNT(DISTINCT region) AS distinct_regions, SORT_ARRAY(COLLECT_SET(region)) AS region_list, AVG(sqft) FILTER (WHERE region = 'South') AS south_avg_sqft, ROUND(SUM(revenue) / NULLIF(COUNT(CASE WHEN region = 'North' THEN 1 END), 0), 2) AS revenue_per_north FROM base GROUP BY CASE WHEN revenue >= 4100 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING revenue_per_north < 0 ORDER BY revenue_tier DESC
